import boto3


def get_rekognition_client(region_name="us-east-1"):
    return boto3.client("rekognition", region_name=region_name)


def get_translate_client(region_name="us-east-1"):
    return boto3.client("translate", region_name=region_name)


def get_comprehend_client(region_name="us-east-1"):
    return boto3.client("comprehend", region_name=region_name)


def get_s3_client(region_name="us-east-1"):
    return boto3.client("s3", region_name=region_name)

def normalize_labels(labels_response):
    return [
        {"name": label["Name"], "confidence": label["Confidence"] / 100.0}
        for label in labels_response.get("Labels", [])
    ]

def normalize_text_detections(text_response):
    return [
        {"text": text["DetectedText"], "confidence": text["Confidence"] / 100.0, "type": text["Type"]}
        for text in text_response.get("TextDetections", [])
    ]

def normalize_moderation_labels(moderation_response):
    return [
        {"name": label["ParentName"] + ": " + label["Name"] if label.get("ParentName") else label["Name"], "confidence": label["Confidence"] / 100.0}
        for label in moderation_response.get("ModerationLabels", [])
    ]

from vision_client import get_rekognition_client
from vision_models import normalize_text_detections


def detect_image_text(payload, config=None):
    config = config or {}
    client = get_rekognition_client(region_name=config.get("region"))
    response = client.detect_text(
        Image={"Bytes": payload["image_bytes"]}
    )
    return {"text_detections": normalize_text_detections(response)}

from vision_client import get_rekognition_client
from vision_models import normalize_moderation_labels


def score_image_safety(payload, config=None):
    config = config or {}
    client = get_rekognition_client(region_name=config.get("region"))
    response = client.detect_moderation_labels(
        Image={"Bytes": payload["image_bytes"]}
    )
    return {"moderation_labels": normalize_moderation_labels(response)}

def image_summary(payload, config=None):
    config = config or {}
    summary_parts = []

    if "labels" in payload and payload["labels"]:
        label_names = [label["name"] for label in payload["labels"]]
        summary_parts.append(f"Detected objects and scenes: {', '.join(label_names)}.")

    if "description" in payload and payload["description"]:
        summary_parts.append(f"Generated description: {payload["description"]}")

    if "text_detections" in payload and payload["text_detections"]:
        detected_texts = [text["text"] for text in payload["text_detections"]]
        summary_parts.append(f"Detected text: '{', '.join(detected_texts)}'.")

    if "moderation_labels" in payload and payload["moderation_labels"]:
        moderation_issues = [label["name"] for label in payload["moderation_labels"]]
        summary_parts.append(f"Moderation issues detected: {', '.join(moderation_issues)}.")

    if not summary_parts:
        return {"summary": "No visual analysis results to summarize."}

    return {"summary": " ".join(summary_parts)}

from vision_client import get_translate_client


def alt_text_translate(payload, config=None):
    config = config or {}
    client = get_translate_client(region_name=config.get("region"))

    text_to_translate = payload.get("text", "")
    target_language_code = config.get("target_language", "es")
    source_language_code = config.get("source_language", "en")

    if not text_to_translate:
        return {"translated_text": ""}

    response = client.translate_text(
        Text=text_to_translate,
        SourceLanguageCode=source_language_code,
        TargetLanguageCode=target_language_code
    )

    return {"translated_text": response["TranslatedText"]}

from vision_client import get_comprehend_client


def visual_safety_text(payload, config=None):
    config = config or {}
    client = get_comprehend_client(region_name=config.get("region"))

    text_to_analyze = payload.get("text", "")

    if not text_to_analyze:
        return {"safety_score": {"overall_sentiment": "NEUTRAL", "sentiment_scores": {}}}

    # Using detect_sentiment as a proxy for text safety. 
    # A more robust solution might involve custom Comprehend models or other services.
    response = client.detect_sentiment(
        Text=text_to_analyze,
        LanguageCode=config.get("language_code", "en")
    )

    return {
        "safety_score": {
            "overall_sentiment": response["Sentiment"],
            "sentiment_scores": response["SentimentScore"]
        }
    }

import json
from vision_client import get_s3_client


def image_asset_archive(payload, config=None):
    config = config or {}
    client = get_s3_client(region_name=config.get("region"))

    bucket_name = config.get("bucket_name")
    object_key_prefix = config.get("object_key_prefix", "image_analysis/")
    image_id = payload.get("image_id", "default_image")

    if not bucket_name:
        return {"status": "error", "message": "S3 bucket_name not provided in config."}

    # Archive image bytes (if available)
    if "image_bytes" in payload:
        image_key = f"{object_key_prefix}{image_id}.jpg"  # Assuming JPEG for example
        client.put_object(
            Bucket=bucket_name,
            Key=image_key,
            Body=payload["image_bytes"],
            ContentType="image/jpeg"
        )
        print(f"Archived image to s3://{bucket_name}/{image_key}")

    # Archive analysis results (as JSON)
    analysis_results = {
        k: v for k, v in payload.items() if k not in ["image_bytes"]
    } # Exclude raw image bytes from JSON artifact
    if analysis_results:
        analysis_key = f"{object_key_prefix}{image_id}_analysis.json"
        client.put_object(
            Bucket=bucket_name,
            Key=analysis_key,
            Body=json.dumps(analysis_results),
            ContentType="application/json"
        )
        print(f"Archived analysis results to s3://{bucket_name}/{analysis_key}")

    return {"status": "success", "message": "Image assets and analysis archived."}
